// Real Electron settings -> marketplace -> DSH model review -> explicit consent -> install.
// The only downloaded executable code is the inert bundle generated by this test.
const { app, ipcMain, BrowserWindow } = require('electron');
app.commandLine.appendSwitch('lang', 'en-US');
const assert = require('node:assert/strict');
const { createHash } = require('node:crypto');
const { existsSync, mkdirSync, readFileSync, writeFileSync } = require('node:fs');
const { basename, isAbsolute, join, resolve, sep } = require('node:path');
const { pathToFileURL } = require('node:url');
const { startRegistry } = require('./fixtures/plugin-marketplace-registry.cjs');
const root = join(__dirname, '..');
const reports = join(root, '.test-data', 'plugin-marketplace-native');
const data = join(reports, String(Date.now()));
const home = join(data, 'core');
const profile = join(home, 'profiles', 'desktop');
mkdirSync(profile, { recursive: true });
process.env.DSH_DESKTOP_DATA_DIR = data;
process.env.DSH_DESKTOP_CONFIG_HOME = home;
process.env.DSH_HOME = home;
process.env.DSH_TELEMETRY_DISABLED = '1';
const report = { checks: [], failures: [], console: [], externalRequests: [], data };
let registry, finished = false, started = false, failureCode = 0;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const timeout = setTimeout(() => finish(new Error('Marketplace integration timeout')), 140000);
async function until(fn, label, duration = 15000) {
  const start = Date.now();
  while (Date.now() - start < duration) { const result = await fn(); if (result) return result; await sleep(80); }
  throw new Error(label);
}
const sanitize = text => String(text).replace(/token=[^\s&"']+/g, 'token=[redacted]');
const originalLog = console.log;
console.log = (...values) => {
  originalLog(...values);
  if (!finished && values.some(value => typeof value === 'string' && value.includes('plugin tree failed to load'))) {
    setImmediate(() => finish(new Error('Production host failed to boot; see the runtime error above')));
  }
};
function finish(error) {
  if (finished) return;
  finished = true;
  if (error) { report.failures.push(sanitize(error.stack ?? error)); failureCode = 1; }
  clearTimeout(timeout);
  registry?.close();
  report.registryRequests = registry?.requests;
  report.modelRequests = registry?.modelRequests.map(request => ({ model: request.model, stream: request.stream, tools: request.tools?.length ?? 0 }));
  if (registry) report.packageCommands = packageCommands();
  writeFileSync(join(data, 'report.json'), JSON.stringify(report, null, 2));
  writeFileSync(join(reports, 'report.json'), JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report, null, 2));
  app.quit();
}
app.on('quit', () => { if (failureCode) process.exit(failureCode); });
app.on('web-contents-created', (_event, contents) => contents.on('console-message', details => {
  if (details.level === 'error') report.console.push(sanitize(details.message));
}));
const originalHandle = ipcMain.handle.bind(ipcMain);
ipcMain.handle = (channel, listener) => originalHandle(channel, async (...args) => {
  if (channel === 'desktop:external') { report.externalRequests.push(args[1]); return; }
  const result = await listener(...args);
  if (channel === 'desktop:ready' && !started) {
    started = true;
    setTimeout(() => run(args[0].sender).then(() => finish()).catch(async error => {
      report.ui = await args[0].sender.executeJavaScript(`({text:document.body.innerText.slice(0,9000),buttons:Array.from(document.querySelectorAll('button')).map(b=>({text:b.textContent,label:b.getAttribute('aria-label'),disabled:b.disabled})).slice(-60)})`).catch(() => null);
      finish(error);
    }), 300);
  }
  return result;
});
function packageCommands() {
  return readFileSync(registry.packageCommands, 'utf8').trim().split('\n').filter(Boolean).map(line => JSON.parse(line));
}
async function run(host) {
  const window = BrowserWindow.fromWebContents(host);
  window.setSize(1100, 820);
  host.setBackgroundThrottling(false);
  window.show();
  window.focus();
  const js = code => host.executeJavaScript(code);
  const screenshot = async (file, selector) => {
    window.show(); window.focus();
    await js(`new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))`);
    assert.equal(await js(`(() => {const element=document.querySelector(${JSON.stringify(selector)});const rect=element?.getBoundingClientRect();return !!rect&&rect.width>0&&rect.height>0;})()`), true, 'Screenshot target is not visible');
    await sleep(200);
    writeFileSync(file, (await host.capturePage()).toPNG());
  };
  const clickText = async (text, scope = 'document') => {
    await until(() => js(`(() => { const root=${scope};const button=Array.from(root?.querySelectorAll('button')??[]).find(b=>${JSON.stringify(text)}.includes(b.textContent.trim())&&!b.disabled);if(!button)return false;button.click();return true;})()`), 'Missing enabled button: ' + text.join(' / '));
  };
  const manifest = () => JSON.parse(readFileSync(join(profile, 'package.json'), 'utf8'));
  const installed = () => !!manifest().dependencies?.[registry.name];
  const enabled = () => manifest().dsh.profile.bundles.includes(registry.name);
  const card = `document.querySelector('[data-marketplace-package="${registry.name}"]')`;
  const dialog = `Array.from(document.querySelectorAll('[role="dialog"]')).at(-1)`;
  const review = `document.querySelector('[data-plugin-security-review]')`;
  const assertNotInstalled = () => {
    assert.equal(installed(), false, 'Review or cancellation changed the profile dependency');
    assert.equal(enabled(), false, 'Review or cancellation enabled the bundle');
    assert.equal(existsSync(join(profile, 'node_modules', registry.name)), false);
    assert.equal(packageCommands().some(command => command.args.includes('add')), false, 'pnpm add ran before explicit consent');
  };
  await js(`Array.from(document.querySelectorAll('button')).find(b=>['继续','Continue'].includes(b.textContent))?.click()`);
  await sleep(400);
  await js(`Array.from(document.querySelectorAll('button')).find(b=>['稍后配置','Configure later'].includes(b.textContent))?.click()`);
  assert.equal(installed(), false);
  assert.equal(existsSync(join(profile, 'node_modules', registry.name)), false);
  assert.equal(existsSync(join(root, '.runtime/node_modules', registry.name)), false);
  await clickText(['插件', 'Plugins']);
  await until(() => js(`!!document.querySelector('[data-plugin-panel]')`), 'Official Plugins page missing');
  assert.equal(await js(`(() => {const button=document.querySelector('button.VOzbGW_trigger');if(!button)return false;button.click();return true;})()`), true, 'Settings entry missing');
  await until(() => js(`Array.from(document.querySelectorAll('button')).some(b=>['插件市场','Plugin marketplace'].includes(b.textContent.trim()))`), 'Marketplace settings entry missing');
  await clickText(['插件市场', 'Plugin marketplace']);
  await until(() => js(`!!document.querySelector('[data-plugin-marketplace] input[aria-label="搜索插件市场"]')`), 'Marketplace independent settings page missing');
  report.checks.push('Open Settings and the independent Plugin Marketplace page in the production Electron renderer');
  await js(`{const input=document.querySelector('[aria-label="搜索插件市场"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,${JSON.stringify(registry.name)});input.dispatchEvent(new Event('input',{bubbles:true}));}`);
  await clickText(['搜索'], `document.querySelector('[data-plugin-marketplace]')`);
  await until(() => js(`!!${card}`), 'Generated remote bundle absent from search results');
  assert.ok(registry.requests.some(request => request.path === '/-/v1/search' && request.query?.includes(registry.name)), 'Search bypassed the real backend registry request');
  assert.ok(registry.requests.some(request => request.path === '/' + registry.name || request.path === '/' + registry.name + '/' + registry.version), 'Bundle metadata was not checked');
  assert.equal(installed(), false, 'Searching installed a package');
  assert.equal(existsSync(join(profile, 'node_modules', registry.name)), false);
  report.checks.push('Search reaches the fixed-endpoint backend through the test-only registry mapping and returns an uninstalled bundle');
  assert.equal(await js(`${card}.querySelector('[data-marketplace-downloads]')?.textContent.includes('1,234')`), true, 'Monthly npm downloads missing');
  assert.equal(await js(`${card}.querySelector('[data-marketplace-repository]')?.textContent.includes('GitHub')`), true, 'GitHub repository link missing');
  await js(`${card}.querySelector('[data-marketplace-repository]').click()`);
  await until(() => report.externalRequests.length > 0, 'GitHub button did not request an external link');
  assert.deepEqual(report.externalRequests, [registry.githubUrl], 'GitHub button did not use the normalized published repository');
  assert.ok(registry.requests.some(request => request.path === '/downloads/point/last-month/' + registry.name));
  report.checks.push('Marketplace displays the verified GitHub repository and package-wide monthly npm download count');
  await clickText(['安装'], card);
  await until(() => js(`Array.from(document.querySelectorAll('[role="dialog"] input')).some(input=>input.value===${JSON.stringify(registry.spec)})`), 'Official installation dialog was not prefilled with the selected exact version');
  assert.equal(await js(`Array.from(document.querySelectorAll('[role="dialog"] input')).filter(input=>input.value===${JSON.stringify(registry.spec)}&&input.getBoundingClientRect().height>0).length`), 1, 'Mounted Plugins page and Marketplace created duplicate installation dialogs');
  report.checks.push('Marketplace result opens the official installation dialog prefilled with name@version');
  await clickText(['安装', 'Install'], dialog);
  await until(() => js(`${review}?.getAttribute('data-install-phase')==='review'`), 'DSH model review report did not appear', 30000);
  const reviewFailure = await js(`${review}.querySelector('[role="alert"]')?.textContent`);
  if (reviewFailure) throw new Error('DSH review failed: ' + reviewFailure);
  assert.ok(registry.modelRequests.length >= 1, 'Review bypassed the real DSH LLM provider');
  for (const request of registry.modelRequests) {
    assert.equal(request.model, 'marketplace-review');
    assert.equal(request.tools?.length ?? 0, 0, 'Reviewer exposed tools to the model');
    assert.ok(JSON.stringify(request.messages).includes('marketplaceAcceptanceFixture'), 'Model did not receive the inspected fixture source');
  }
  assert.equal(await js(`!!${review}.querySelector('[data-plugin-security-risk="high"]')`), true, 'High-risk result was not rendered');
  assert.equal(await js(`Array.from(${review}.querySelectorAll('button')).find(button=>button.textContent.trim()==='继续安装')?.disabled`), true, 'Risky installation was enabled without acknowledgement');
  assertNotInstalled();
  report.reviewScreenshot = join(data, 'marketplace-high-risk-review.png');
  await screenshot(report.reviewScreenshot, '[data-plugin-security-review]');
  report.checks.push('The real DSH LLM service reviews inspected source through a local HTTP model with no tools; high risk blocks installation until acknowledged');
  await clickText(['取消安装'], review);
  await until(() => js(`!document.querySelector('[data-plugin-security-review]')`), 'Cancelling review did not close the report');
  assertNotInstalled();
  report.checks.push('Cancelling the review leaves profile dependencies and enabled bundles unchanged and never invokes pnpm add');
  const priorReviews = registry.modelRequests.length;
  await clickText(['安装'], card);
  await until(() => js(`Array.from(document.querySelectorAll('[role="dialog"] input')).some(input=>input.value===${JSON.stringify(registry.spec)})`), 'Second official installation dialog missing');
  await clickText(['安装', 'Install'], dialog);
  await until(() => js(`${review}?.getAttribute('data-install-phase')==='review'`), 'Second DSH review report missing', 30000);
  assert.ok(registry.modelRequests.length > priorReviews, 'Second install reused approval instead of reviewing again');
  assertNotInstalled();
  assert.equal(await js(`${review}.querySelector('[data-plugin-security-sha256]')?.textContent`), registry.sha256, 'Report did not identify the reviewed tarball SHA-256');
  const downloadedBeforeConsent = registry.requests.filter(request => request.path.endsWith('.tgz')).length;
  assert.ok(downloadedBeforeConsent >= 1, 'Review did not fetch the source archive');
  assert.equal(await js(`(() => {const checkbox=${review}.querySelector('input[type="checkbox"]');if(!checkbox||checkbox.checked)return false;checkbox.click();return true;})()`), true, 'Risk confirmation checkbox missing or already checked');
  await clickText(['继续安装'], review);
  await until(async () => {
    if (await js(`!!document.querySelector('[role="dialog"] input[aria-invalid="true"]')`)) throw new Error('Official package inspection failed: ' + await js(`${dialog}?.textContent`));
    const phase = await js(`document.querySelector('[data-install-phase]')?.getAttribute('data-install-phase')`);
    if (phase === 'failed') throw new Error('Official installation failed: ' + await js(`document.body.innerText.slice(-7000)`));
    return phase === 'done';
  }, 'Official package installation did not complete', 40000);
  assert.equal(installed(), true);
  const additions = packageCommands().filter(command => command.args.includes('add'));
  assert.equal(additions.length, 1, 'Explicit confirmation must start exactly one package installation');
  const archive = additions[0].args.find(argument => typeof argument === 'string' && argument.endsWith('.tgz'))?.replace(/^file:/, '');
  assert.ok(archive && isAbsolute(archive) && resolve(archive).startsWith(profile + sep), 'Installation did not use the isolated profile reviewed archive');
  assert.equal(basename(archive), registry.sha256 + '.tgz');
  assert.equal(createHash('sha256').update(readFileSync(archive)).digest('hex'), registry.sha256, 'Installed bytes differ from the reviewed archive');
  assert.equal(registry.requests.filter(request => request.path.endsWith('.tgz')).length, downloadedBeforeConsent, 'Installation fetched an unreviewed replacement archive');
  report.reviewedArchive = { path: archive, sha256: registry.sha256 };
  const downloaded = JSON.parse(readFileSync(join(profile, 'node_modules', registry.name, 'package.json'), 'utf8'));
  assert.equal(downloaded.name, registry.name);
  assert.equal(downloaded.dependencies, undefined);
  assert.equal(downloaded.scripts, undefined);
  report.checks.push('After explicit consent, bundled pnpm installs the exact locally cached archive identified by the review SHA-256 without downloading replacement bytes');
  await clickText(['立即启用', 'Enable now'], dialog);
  await until(() => enabled(), 'Installed bundle was not enabled in the profile');
  await until(() => js(`!document.querySelector('[data-install-phase]')`), 'Official enable flow did not close the installation dialog');
  await until(() => js(`${card}?.getAttribute('data-marketplace-state')==='enabled'`), 'Marketplace did not refresh the enabled state');
  report.enabledScreenshot = join(data, 'marketplace-enabled.png');
  await screenshot(report.enabledScreenshot, '[data-marketplace-state="enabled"]');
  report.checks.push('Official enable action applies the bundle and the marketplace result refreshes its enabled state');
  assert.equal(await js(`(() => {const modal=document.querySelector('[data-plugin-marketplace]')?.closest('[role="dialog"]');const close=Array.from(modal?.querySelectorAll('button')??[]).find(b=>['关闭','关闭设置','Close','Close settings'].includes(b.getAttribute('aria-label')??b.textContent.trim()));if(!close)return false;close.click();return true;})()`), true, 'Settings close control missing');
  await until(() => js(`!!document.querySelector('[data-plugin-package="${registry.name}"]')`), 'Installed package missing from the underlying official Plugins page');
  assert.equal(await js(`(() => {const button=document.querySelector('[data-plugin-package="${registry.name}"] button');if(!button||button.disabled)return false;button.click();return true;})()`), true, 'Installed package detail button missing');
  await until(() => js(`!!document.querySelector('[data-plugin-detail="${registry.name}"]')`), 'Installed package detail did not open');
  await until(() => js(`Array.from(document.querySelectorAll('[data-plugin-detail="${registry.name}"] [data-plugin-row]')).some(row=>row.textContent.includes('marketplace-acceptance-fixture')&&/运行中|Running/.test(row.textContent))`), 'Installed fixture entry did not become an active host plugin');
  report.checks.push('The official package detail reports the generated host plugin entry as running');
  await clickText(['卸载', 'Uninstall'], `document.querySelector('[data-plugin-detail="${registry.name}"]')`);
  await until(() => js(`Array.from(document.querySelectorAll('[role="dialog"]')).some(node=>node.textContent.includes('卸载')||node.textContent.includes('Uninstall'))`), 'Official uninstall confirmation missing');
  await clickText(['卸载', 'Uninstall'], dialog);
  await until(() => !installed() && !enabled(), 'Uninstall did not remove the isolated profile dependency and bundle entry', 30000);
  assert.equal(existsSync(join(profile, 'node_modules', registry.name)), false);
  report.checks.push('Official uninstall confirmation removes the installed dependency and enabled bundle from the isolated profile');
  const { createRequire } = require('node:module');
  const yaml = createRequire(join(root, '.runtime/package.json'))('yaml');
  const layout = yaml.parse(readFileSync(join(profile, 'node_modules/.modules.yaml'), 'utf8'));
  assert.equal(layout.storeDir, join(data, 'pnpm-store/v11'));
  assert.ok(registry.requests.every(request => request.path === '/-/v1/search' || request.path === '/downloads/point/last-month/' + registry.name || request.path.startsWith('/' + registry.name)), 'Unexpected registry package request');
  report.checks.push('All package requests target the fixture and all pnpm store writes stay in the test directory');
}
(async () => {
  registry = await startRegistry(data);
  report.package = registry.spec;
  registry.setModelReport({
    summary: '隔离验收：测试模型标记高风险，以验证安装前的明确确认。', risk: 'high', findings: [],
    limitations: ['这是本地确定性测试报告，不代表第三方插件的安全结论。'],
  });
  writeFileSync(join(home, 'settings.yaml'), JSON.stringify({
    'llm-pi-ai': { providers: { 'marketplace-local': {
      displayName: 'Isolated marketplace review fixture', apiKeyEnv: 'DSH_MARKETPLACE_LOCAL_KEY',
      api: 'openai-completions', baseURL: registry.origin + '/v1',
      models: [{ id: 'marketplace-review', contextWindow: 32768, maxTokens: 4096 }],
    } } },
    'agent-default-model': { provider: 'marketplace-local', model: 'marketplace-review' },
  }), { mode: 0o600 });
  writeFileSync(join(home, '.credentials.yaml'), JSON.stringify({
    version: 1, refs: { DSH_MARKETPLACE_LOCAL_KEY: 'disposable-marketplace-fixture' }, records: {},
  }), { mode: 0o600 });
  process.env.NODE_OPTIONS = `--import=${pathToFileURL(registry.preload).href}`;
  process.env.npm_config_userconfig = join(data, 'empty-npmrc');
  process.env.npm_config_registry = registry.origin;
  writeFileSync(process.env.npm_config_userconfig, '');
  // pnpm view uses npm's per-project registry config; its runner scrubs parent env.
  writeFileSync(join(profile, '.npmrc'), `registry=${registry.origin}\nignore-scripts=true\ncache=${join(data, 'npm-cache')}\n`);
  writeFileSync(join(profile, 'pnpm-workspace.yaml'), JSON.stringify({
    packages: [], registry: registry.origin, ignoreScripts: true,
    storeDir: join(data, 'pnpm-store'), cacheDir: join(data, 'pnpm-cache'),
    managePackageManagerVersions: false, updateNotifier: false,
  }));
  app.setAppPath(root);
  require('../dist/main/index.cjs');
})().catch(finish);
